import*as THREE from'three';import{materials}from'../../core/index.js';import{addCadParts}from'../../modeling/cad.js';import{mesh,slab,screw}from'../../modeling/parts.js';import data from'./geometry-data.js';import{grove,terminal}from'./connectors.js';import{addStickers}from'./stickers.js';
const tau=Math.PI*2;
function board(host){
 const s=new THREE.Shape(),x=10.4,y=-4,r=3.6,a=Math.acos((x-8)/r),dy=Math.sqrt(r*r-(x-8)**2);
 s.moveTo(-5.5,-14.5);s.lineTo(-7.7,-14.5);s.lineTo(-x,-12.5);s.lineTo(-x,y-dy);s.absarc(-8,y,r,Math.PI+a,Math.PI-a,false);s.lineTo(-x,12.4);s.lineTo(-8.5,14.3);s.lineTo(8.5,14.3);s.lineTo(x,12.4);s.lineTo(x,y+dy);s.absarc(8,y,r,a,tau-a,false);s.lineTo(x,-12.5);s.lineTo(7.7,-14.5);s.lineTo(5.5,-14.5);s.lineTo(5.5,-8.1);s.lineTo(-5.5,-8.1);s.closePath();const bore=new THREE.Path();bore.absarc(0,-4,2.1,0,tau,false);s.holes.push(bore);
 const pcb=mesh(host.body,new THREE.ExtrudeGeometry(s,{depth:.8,bevelEnabled:false,curveSegments:48}),materials.plastic(0x167447,{roughness:.88}),[0,0,-1.7],'Mini CAN fixed PCB with actual mounting reliefs and retaining bore');pcb.userData={role:'physical-pcb',scope:'Appearance reconstruction from own shell and schematic;concealed outline,plane and placement inferred,no traces/electrical model'};
 const dark=materials.plastic(0x252923,{roughness:.82}),metal=materials.metal(0xb7bcaa,{roughness:.47}),ceramic=materials.plastic(0xbfb083,{roughness:.86});
 const tja=slab(host.body,3.9,4.9,1.7,.13,[-4.45,2.25,-.9],dark,[],.015);tja.name='Mini CAN U3 TJA1051T3 SO8 physical non-isolated CAN transceiver';const tjaLeads=[];for(const sign of[-1,1])for(let i=0;i<4;i++)tjaLeads.push(mesh(host.body,new THREE.BoxGeometry(1.15,.43,.2),metal,[-4.45+sign*2.42,2.25+(i-1.5)*1.27,-.65],'Mini CAN U3 SO8 gull-wing lead '+(tjaLeads.length+1)));
 const buck=slab(host.body,1.7,3,.95,.09,[3.6,1.3,-.9],dark,[],.015);buck.name='Mini CAN U1 ME3116 SOT23-6 physical buck package';const buckLeads=[];for(const sign of[-1,1])for(let i=0;i<3;i++)buckLeads.push(mesh(host.body,new THREE.BoxGeometry(.6,.32,.15),metal,[3.6+sign*1.05,1.3+(i-1)*.95,-.68],'Mini CAN U1 SOT23-6 physical lead'));
 const regulator=slab(host.body,1.3,2.9,.9,.09,[6.8,-5.8,-.9],dark,[],.015);regulator.name='Mini CAN U2 MST5333 three-pin physical regulator';const regulatorLeads=[];for(const[dx,dy]of[[-.85,-.95],[-.85,.95],[.85,0]])regulatorLeads.push(mesh(host.body,new THREE.BoxGeometry(.6,.35,.15),metal,[6.8+dx,-5.8+dy,-.69],'Mini CAN U2 SOT23 physical lead'));
 const inductor=slab(host.body,3,3,1.2,.25,[3.7,5.4,-.9],materials.plastic(0x474c43,{roughness:.79}),[],.03);inductor.name='Mini CAN L1 36.8uH 3012 fixed inductor';for(const side of[-1,1])mesh(host.body,new THREE.BoxGeometry(.35,2.5,.25),metal,[3.7+side*1.34,5.4,-.7],'Mini CAN L1 solder termination');
 const passives=[];for(const[n,x,y,w,h,d]of[['D3 SMF30CA',-6.9,9.3,2.7,1.8,1.1],['C8 input capacitor',-3.4,8.9,2.2,1.4,1.0],['D2 B5819W',6.6,4.8,1.6,.95,.65],['D4 DSS34',6.5,7.1,2.7,1.5,1.1],['R1 fixed120R',-5.4,5.9,1.6,.8,.5],['DZ1 CANH protection',-8.4,4.1,1.1,.8,.6],['DZ2 CANL protection',-8.4,1.6,1.1,.8,.6],['C1 decoupling',-.4,2.9,1.4,.9,.65],['C2 decoupling',-.4,.5,1.4,.9,.65],['C3 input',4.1,-6,1.6,.9,.7],['C4 output',8.6,-7.7,1.4,.9,.65],['C6 rail',2.1,8.1,1.6,.9,.7],['C9 output',4.1,9.2,1.6,.9,.7],['R5 LED1',-7.8,-9.4,1.2,.65,.55],['R3 feedback',7.8,1.2,1.2,.65,.55],['R4 feedback',7.8,-.5,1.2,.65,.55],['C7 bootstrap',3.4,-1,1.2,.65,.55]]){const q=slab(host.body,w,h,d,.06,[x,y,-.9],n[0]==='C'?ceramic:dark,[],.01);q.name='Mini CAN fixed '+n;passives.push(q);for(const sign of[-1,1])mesh(host.body,new THREE.BoxGeometry(.22,h,.16),metal,[x+sign*(w/2-.08),y,-.78],'Mini CAN passive solder end');}
 const ledBase=slab(host.body,1.6,.85,.45,.08,[-7.8,-11.4,-.9],materials.plastic(0xe4e1ce,{roughness:.71}),[],.015);ledBase.name='Mini CAN concealed LED1 White substrate';const hiddenLed=mesh(host.body,new THREE.BoxGeometry(.85,.55,.2),materials.plastic(0xece8d2,{roughness:.47}),[-7.8,-11.4,-.35],'Mini CAN concealed White LED1 non-emissive resin');for(const sign of[-1,1])mesh(host.body,new THREE.BoxGeometry(.22,.85,.25),metal,[-7.8+sign*.65,-11.4,-.72],'Mini CAN concealed LED1 solder end');return{pcb,tja,tjaLeads,buck,buckLeads,regulator,regulatorLeads,inductor,passives,ledBase,hiddenLed};
}
function labelCarrier(host){const s=new THREE.Shape();s.moveTo(-5.1,-8.6);s.lineTo(5.1,-8.6);s.lineTo(5.1,-6.8);s.quadraticCurveTo(4.0,-5.6,4.4,-3.3);s.quadraticCurveTo(4.8,-.9,8,-.5);s.lineTo(8,6.25);s.lineTo(-8,6.25);s.lineTo(-8,-.5);s.quadraticCurveTo(-4.8,-.9,-4.4,-3.3);s.quadraticCurveTo(-4,-5.6,-5.1,-6.8);s.closePath();const front=mesh(host.body,new THREE.ExtrudeGeometry(s,{depth:.05,bevelEnabled:false,curveSegments:32}),materials.plastic(0xe4e6e1,{roughness:.86}),[0,0,3.96],'Mini CAN physical die-cut front adhesive substrate');const back=slab(host.body,16,12.2,.05,.05,[0,7.35,-3.845],materials.plastic(0xe4e6e1,{roughness:.86}),[],.005);back.name='Mini CAN physical rear adhesive substrate';return{front,back};}
export function buildMiniCAN(host){const parts=addCadParts(host,data,{shell:materials.plastic(0xe8e9e3,{roughness:.79})}),pcb=board(host),input=grove(host),output=terminal(host),fixing=screw(host.body,[0,-4,-3.88],'back',1.28);fixing.name='Mini CAN fixed recessed rear retaining hex screw';mesh(host.body,new THREE.CylinderGeometry(.62,.62,3.7,32).rotateX(Math.PI/2),materials.metal(0x999f91),[0,-4,-1.9],'Mini CAN concealed fixed retaining screw shank');const labels=labelCarrier(host);host.miniCanAssembly={parts,pcb,input,output,fixing,frontCarrier:labels.front,backCarrier:labels.back};host.unitStickers=addStickers(host);}
